// Findability index — record JAH-GGN-KEYFINDER-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"range_m": 60, "network_m": 1000000, "price_usd": 30};
var value = (m.range_m*m.network_m/m.price_usd);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GGN-KEYFINDER-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GGN-KEYFINDER-000001|' + value.toFixed(2) + ' findability index');

